10:   avatar: ReactNode;
11:   /** Small plain-language line above the description, e.g. "Email · 2m ago". */
12:   meta: ReactNode;
13:   /** The one description line always visible while closed. */
14:   title: ReactNode;
15:   /** Everything the card reveals when opened. */
16:   children: ReactNode;
17:   /** Start open; defaults closed like a phone notification stack. */
18:   defaultOpen?: boolean;
19:   /** Accessible label for the reveal region. */
20:   bodyId: string;
21:   /** Urgency level determining 3px left urgency rail color. */
22:   urgency?: Urgency | string | null;
23:   /** Proactivity tag string (e.g. 'Urgent Action', 'Decision Needed'). */
24:   proactivityTag?: string | null;
25: }
26: 
27: /**
28:  * The standardized card shell every surface reuses: a phone-notification pill that opens downward
29:  * into its details. Monochrome, sharp-cornered at the shell scale, animated with one spring.
30:  */
31: export function NotificationCard({
32:   avatar,
33:   meta,
34:   title,
35:   children,
36:   defaultOpen = false,
37:   bodyId,
38:   urgency,
39:   proactivityTag,
40: }: Props) {
