47:       ? 'border-l-[3px] border-l-[var(--urgency-high)]'
48:       : urgency === 'medium'
49:       ? 'border-l-[3px] border-l-[var(--urgency-medium)]'
50:       : urgency === 'low'
51:       ? 'border-l-[3px] border-l-[var(--urgency-low)]'
52:       : '';
53: 
54:   return (
55:     <motion.section
56:       layout="position"
57:       className={`card rounded-[18px] ${urgencyRailClass}`.trim()}
58:       initial={false}
59:     >
60:       <button
61:         type="button"
62:         onClick={() => setOpen((value) => !value)}
63:         aria-expanded={open}
64:         aria-controls={open ? bodyId : undefined}
65:         className="flex w-full items-center gap-3.5 px-4 py-3.5 text-left md:px-5"
66:       >
67:         {avatar}
68:         <span className="min-w-0 flex-1">
69:           <span className="flex flex-wrap items-center gap-2 text-[11px] font-semibold uppercase tracking-[0.1em] text-[var(--text-muted)]">
70:             {meta}
71:             {proactivityTag ? (
72:               <span className="rounded-full border border-[var(--tag-proactive-border)] bg-[var(--tag-proactive-bg)] px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.06em] text-[var(--tag-proactive-text)]">
73:                 {proactivityTag}
74:               </span>
75:             ) : null}
76:           </span>
77:           <span className="mt-0.5 block truncate text-[15px] font-semibold leading-snug tracking-[-0.01em] text-[var(--text)]">
78:             {title}
79:           </span>
80:         </span>
81:         <motion.span
82:           animate={{ rotate: open ? 180 : 0 }}
83:           transition={spring}
84:           className="grid h-8 w-8 shrink-0 place-items-center rounded-full text-[var(--text-muted)]"
