1: import { useState } from 'react';
2: import { useMutation, useQueryClient } from '@tanstack/react-query';
3: import { ArrowUpRight, Check, Loader2, Square } from 'lucide-react';
4: import { motion, useReducedMotion } from 'framer-motion';
5: import { useNavigate } from 'react-router-dom';
6: import { api } from '@/lib/api';
7: import { userMessageOf } from '@/lib/errors';
8: import { relativeTime } from '@/lib/format';
9: import { releaseIdempotencyKey } from '@/lib/idempotency';
10: import { runKey, stepLabel, useCancelRun, useDefaultAgentConfig, useRun } from '@/queries/runs';
11: import { CARDS_KEY, useDismissCard } from '@/queries/cards';
12: import NotificationCard from '@/components/ui/NotificationCard';
13: import { SourceAvatar, sourceFor } from '@/components/ui/SourceAvatar';
14: import type { Card, CardAction } from '@/types';
15: 
16: /** Matches MessageItem so briefings and chat arrivals share the same physical feel. */
17: const enterSpring = {
18:   type: 'spring' as const,
19:   stiffness: 480,
20:   damping: 20,
21:   mass: 0.9,
22: };
23: 
24: interface Props {
25:   card: Card;
26:   index: number;
27:   onError: (message: string) => void;
28: }
29: 
30: /**
31:  * A briefing item rendered as the standardized notification card: a circular source avatar, the
32:  * description, and a dropdown that opens its detail and actions. The shell itself is reusable on
33:  * any page; only this file knows card actions.
34:  */
35: export function TaskCard({ card, index, onError }: Props) {
36:   const navigate = useNavigate();
37:   const queryClient = useQueryClient();
38:   const dismissCard = useDismissCard();
39:   const cancelRun = useCancelRun();
40:   const defaultConfig = useDefaultAgentConfig();
41:   const reduced = useReducedMotion();
42: 
43:   /** Set when a card-run action POSTs successfully; drives the inline progress strip. */
44:   const [runId, setRunId] = useState<string | null>(null);
45:   const subscription = useRun(runId);
46: 
47:   const source = sourceFor(card.type);
48:   const due = relativeTime(card.due_at);
49: 
50:   const runAction = useMutation({
51:     mutationFn: ({
52:       action,
53:       cardId,
54:       scope,
55:     }: {
56:       action: CardAction;
57:       cardId: string;
58:       scope: string;
59:     }) => {
60:       // POST /runs requires config_id. Card actions carry their own config when the backend
61:       // attaches one; otherwise the pinned server-side default config runs the card.
62:       const payloadConfigId =
63:         typeof action.payload['config_id'] === 'string' ? action.payload['config_id'] : null;
64:       const configId = payloadConfigId ?? defaultConfig.data?.id;
65:       const prompt = typeof action.payload['initial_prompt'] === 'string' ? action.payload['initial_prompt'] : null;
66:       if (!configId) {
67:         return Promise.reject(
68:           new Error('The agent configuration is not ready yet. Try again in a moment.'),
69:         );
70:       }
71:       return api.createRun(
72:         {
73:           config_id: configId,
74:           card_id: cardId,
75:           initial_prompt: prompt,
76:         },
77:         scope,
78:       );
79:     },
80: 
81:     onSuccess: (run) => {
82:       // The run id is the hook into the events stream, keep it, never drop it.
83:       setRunId(run.id);
84:       queryClient.setQueryData(runKey(run.id), run);
85:       void queryClient.invalidateQueries({ queryKey: CARDS_KEY });
86:     },
87: 
88:     onError: (error) => onError(userMessageOf(error)),
89: 
90:     onSettled: (_data, _error, variables) => releaseIdempotencyKey(variables.scope),
91:   });
92: 
93:   const busy = dismissCard.isPending || runAction.isPending;
94: 
95:   const dispatch = (action: CardAction) => {
96:     const scope = `card-action:${card.id}:${action.id}`;
97: 
98:     switch (action.action_type) {
99:       case 'run':
100:         runAction.mutate({ action, cardId: card.id, scope });
101:         break;
102:       case 'dismiss':
103:         dismissCard.mutate({ cardId: card.id, scope });
104:         break;
105:       case 'reply': {
106:         const seed = typeof action.payload['seed'] === 'string' ? action.payload['seed'] : '';
107:         navigate('/agent/chat', { state: { seed, cardId: card.id } });
108:         break;
109:       }
110:       default:
111:         break;
112:     }
113:   };
114: 
115:   const isKnown = (action: CardAction) =>
116:     (action.action_type === 'run' &&
117:       (typeof action.payload['config_id'] === 'string' || defaultConfig.data !== undefined)) ||
118:     action.action_type === 'dismiss' ||
119:     action.action_type === 'reply';
120: 
121:   const [primary, ...rest] = card.actions;
122:   const isBlocking = card.status === 'awaiting_approval';
123: 
124:   const statusLabel = isBlocking ? 'Waiting on you' : card.due_at ? 'Gentle reminder' : 'For the record';
125:   const finished = subscription.run ? ['completed', 'failed'].includes(subscription.run.status) : false;
126: 
127:   return (
128:     <motion.div
129:       layout
130:       initial={reduced ? { opacity: 0 } : { opacity: 0, y: 18, scale: 0.96 }}
131:       animate={{ opacity: 1, y: 0, scale: 1 }}
132:       exit={{ opacity: 0, scale: 0.96, transition: { duration: 0.2 } }}
133:       transition={reduced ? { duration: 0.2 } : { ...enterSpring, delay: index * 0.07 }}
134:       style={{ transformOrigin: 'top center' }}
135:     >
136:       <NotificationCard
137:         bodyId={`card-body-${card.id}`}
138:         avatar={<SourceAvatar size={36} source={source} />}
139:         urgency={card.urgency}
140:         proactivityTag={card.proactivity_tag}
141:         meta={
142:           <>
143:             <span>{source.name}</span>
144:             <span aria-hidden="true">·</span>
145:             <span className="font-medium tracking-normal">{statusLabel}</span>
146:             {card.verb ? (
147:               <>
148:                 <span aria-hidden="true">·</span>
149:                 <span className="font-medium tracking-normal text-[var(--text)]">{card.verb}</span>
150:               </>
151:             ) : null}
152:             {due ? (
153:               <>
154:                 <span aria-hidden="true">·</span>
155:                 <span className="font-medium tracking-normal">{due}</span>
156:               </>
157:             ) : null}
158:           </>
159:         }
160:         title={card.title}
161:       >
162:         {card.summary ? (
163:           <p className="text-[14px] leading-relaxed text-[var(--text-muted)]">{card.summary}</p>
164:         ) : null}
165: 
166:         {runId && !finished ? (
167:           <div className="mt-4 rounded-[8px] border border-[var(--border)] px-3 py-2.5">
168:             <div className="flex items-center gap-2 text-[13px] font-medium">
169:               <Loader2 size={14} className="animate-spin text-[var(--text-muted)]" strokeWidth={1.75} />
170:               <span className="text-[var(--text-muted)]">
171:                 {subscription.run?.status === 'queued' ? 'Starting' : 'Running'}
172:               </span>
173:               <button
174:                 type="button"
175:                 onClick={() => cancelRun.mutate({ runId, scope: `run:cancel:${runId}` })}
176:                 disabled={cancelRun.isPending}
177:                 className="ml-auto inline-flex items-center gap-1 text-[12px] text-[var(--text-muted)] transition-colors hover:text-[var(--text)]"
178:               >
179:                 <Square size={11} strokeWidth={1.75} />
180:                 Stop
181:               </button>
182:             </div>
183: 
184:             {subscription.steps.length > 0 ? (
185:               <ul className="mt-2 space-y-1.5">
186:                 {subscription.steps.slice(-3).map((step) => (
187:                   <li key={step.step_number} className="flex items-center gap-2 text-[13px] text-[var(--text-muted)]">
188:                     <span className="h-1.5 w-1.5 rounded-full bg-[color-mix(in_srgb,var(--text)_25%,transparent)]" />
189:                     {stepLabel(step)}
190:                   </li>
191:                 ))}
192:               </ul>
193:             ) : null}
194:           </div>
195:         ) : null}
196: 
197:         {runId && finished && subscription.run ? (
198:           <p className="mt-4 text-[13px] text-[var(--text-muted)]">
199:             {subscription.run.status === 'completed' ? 'Ran to completion.' : 'That run failed.'}
200:           </p>
201:         ) : null}
202: 
203:         <div className="mt-4 flex flex-wrap items-center gap-2.5">
204:           {primary ? (
205:             <button
206:               type="button"
207:               onClick={() => dispatch(primary)}
208:               disabled={busy || !isKnown(primary)}
209:               className="btn btn-primary"
210:             >
211:               {isBlocking ? (
212:                 <Check size={16} strokeWidth={1.75} />
213:               ) : (
214:                 <ArrowUpRight size={16} strokeWidth={1.5} />
215:               )}
216:               {primary.verb && primary.verb !== primary.label ? (
217:                 <span>
218:                   <span className="font-semibold">{primary.verb}</span>
219:                   <span className="opacity-75 font-normal"> · {primary.label}</span>
220:                 </span>
221:               ) : (
222:                 primary.label
223:               )}
224:             </button>
225:           ) : null}
226: 
227:           {rest.slice(0, 2).map((action) => (
228:             <button
229:               key={action.id}
230:               type="button"
231:               onClick={() => dispatch(action)}
232:               disabled={busy || !isKnown(action)}
233:               className="btn btn-ghost"
234:             >
235:               {action.verb && action.verb !== action.label ? (
236:                 <span>
237:                   <span className="font-semibold">{action.verb}</span>
238:                   <span className="opacity-75 font-normal"> · {action.label}</span>
239:                 </span>
240:               ) : (
241:                 action.label
242:               )}
243:             </button>
244:           ))}
245: 
246:           <button
247:             type="button"
248:             onClick={() =>
249:               navigate('/agent/chat', {
250:                 state: { seed: `Tell me about: ${card.title}`, cardId: card.id },
251:               })
252:             }
253:             className="ml-auto inline-flex h-10 items-center gap-1.5 rounded-full px-3 text-sm font-medium text-[var(--text-muted)] transition-colors hover:text-[var(--text)]"
254:           >
255:             Discuss with Vigil
256:             <ArrowUpRight size={14} strokeWidth={1.5} />
257:           </button>
258:         </div>
259:       </NotificationCard>
260:     </motion.div>
261:   );
262: }
263: 
264: export default TaskCard;
265: 
